/** Never put query credentials (or URL userinfo) in operational logs. */
export function proxyLogUrl(url: string): string {
  try {
    const parsed = new URL(url);
    return parsed.origin + parsed.pathname;
  } catch {
    return "[invalid upstream URL]";
  }
}

